CREATE OR ALTER PROCEDURE [dbo].[uspApprovalStep_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ApprovalRequestId UNIQUEIDENTIFIER = NULL
	, @ApproverUserId UNIQUEIDENTIFIER = NULL
	, @DecisionStatus NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ApprovalRequestId]
			, j1.[RequestNo] AS [ApprovalRequestName]
			, t.[StepNo]
			, t.[ApproverUserId]
			, t.[ApproverRoleCode]
			, t.[DecisionStatus]
			, t.[AssignedAt]
			, t.[DueAt]
			, t.[DecidedAt]
			, t.[DecisionNote]
			, t.[CreatedDate]
		FROM [dbo].[ApprovalStep] AS t
		LEFT JOIN [dbo].[ApprovalRequest] AS j1 ON j1.[Id] = t.[ApprovalRequestId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[ApproverRoleCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@ApprovalRequestId IS NULL OR t.[ApprovalRequestId] = @ApprovalRequestId)
			AND (@ApproverUserId IS NULL OR t.[ApproverUserId] = @ApproverUserId)
			AND (ISNULL(@DecisionStatus, '') = '' OR t.[DecisionStatus] = @DecisionStatus)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approvalRequestId' THEN r.[ApprovalRequestId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approvalRequestId' THEN r.[ApprovalRequestId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approvalRequestName' THEN r.[ApprovalRequestName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approvalRequestName' THEN r.[ApprovalRequestName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'stepNo' THEN r.[StepNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'stepNo' THEN r.[StepNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approverUserId' THEN r.[ApproverUserId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approverUserId' THEN r.[ApproverUserId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approverRoleCode' THEN r.[ApproverRoleCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approverRoleCode' THEN r.[ApproverRoleCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'decisionStatus' THEN r.[DecisionStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'decisionStatus' THEN r.[DecisionStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'assignedAt' THEN r.[AssignedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'assignedAt' THEN r.[AssignedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dueAt' THEN r.[DueAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dueAt' THEN r.[DueAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'decidedAt' THEN r.[DecidedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'decidedAt' THEN r.[DecidedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'decisionNote' THEN r.[DecisionNote] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'decisionNote' THEN r.[DecisionNote] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
